(window.__qhadithX=window.__qhadithX||{})[19]={"28":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3155","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3155","x":"Narrated Al-Mughirah bin Shu'bah:\n\n\"The Messenger of Allah (ﷺ) sent me to Najran. They said to me: 'Do you people not recite: O sister of Harun (19:28) - while between Musa and 'Eisa there is such (gap) as there is?' I did not know how to respond to them. So when I returned to the Prophet (ﷺ), I told him about that, and he said: 'Why didn't you tell them that they were named after their Prophets and righteous people before them.'\"","ar":"حَدَّثَنَا أَبُو سَعِيدٍ الأَشَجُّ، وَأَبُو مُوسَى مُحَمَّدُ بْنُ الْمُثَنَّى قَالاَ حَدَّثَنَا ابْنُ إِدْرِيسَ، عَنْ أَبِيهِ، عَنْ سِمَاكِ بْنِ حَرْبٍ، عَنْ عَلْقَمَةَ بْنِ وَائِلٍ، عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ بَعَثَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم إِلَى نَجْرَانَ فَقَالُوا لِي أَلَسْتُمْ تَقْرَءُونَ ‏:‏ ‏(‏ يَا أُخْتَ هَارُونَ ‏)‏ وَقَدْ كَانَ بَيْنَ عِيسَى وَمُوسَى مَا كَانَ فَلَمْ أَدْرِ مَا أُجِيبُهُمْ ‏.‏ فَرَجَعْتُ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَأَخْبَرْتُهُ فَقَالَ ‏\"‏ أَلاَّ أَخْبَرْتَهُمْ أَنَّهُمْ كَانُوا يُسَمُّونَ بِأَنْبِيَائِهِمْ وَالصَّالِحِينَ قَبْلَهُمْ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ غَرِيبٌ لاَ نَعْرِفُهُ إِلاَّ مِنْ حَدِيثِ ابْنِ إِدْرِيسَ ‏.‏","v":[]}],"39":[{"c":"Sahih Bukhari","r":"Hadith 4730","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4730","x":"Narrated Abu Sa`id Al-Khudri:\n\nAllah's Messenger (ﷺ) said, \"On the Day of Resurrection Death will be brought forward in the shape of a black and white ram. Then a call maker will call, 'O people of Paradise!' Thereupon they will stretch their necks and look carefully. The caller will say, 'Do you know this?' They will say, 'Yes, this is Death.' By then all of them will have seen it. Then it will be announced again, 'O people of Hell !' They will stretch their necks and look carefully. The caller will say, 'Do you know this?' They will say, 'Yes, this is Death.' And by then all of them will have seen it. Then it (that ram) will be slaughtered and the caller will say, 'O people of Paradise! Eternity for you and no death O people of Hell! Eternity for you and no death.\"' Then the Prophet, recited:-- 'And warn them of the Day of distress when the case has been decided, while (now) they are in a state of carelessness (i.e. the people of the world) and they do not believe.' (19.39)","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصِ بْنِ غِيَاثٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، حَدَّثَنَا أَبُو صَالِحٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يُؤْتَى بِالْمَوْتِ كَهَيْئَةِ كَبْشٍ أَمْلَحَ فَيُنَادِي مُنَادٍ يَا أَهْلَ الْجَنَّةِ، فَيَشْرَئِبُّونَ وَيَنْظُرُونَ فَيَقُولُ هَلْ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ، وَكُلُّهُمْ قَدْ رَآهُ، ثُمَّ يُنَادِي يَا أَهْلَ النَّارِ، فَيَشْرَئِبُّونَ وَيَنْظُرُونَ، فَيَقُولُ هَلْ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ، وَكُلُّهُمْ قَدْ رَآهُ، فَيُذْبَحُ ثُمَّ يَقُولُ يَا أَهْلَ الْجَنَّةِ، خُلُودٌ فَلاَ مَوْتَ، وَيَا أَهْلَ النَّارِ، خُلُودٌ فَلاَ مَوْتَ ثُمَّ قَرَأَ ‏{‏وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الأَمْرُ وَهُمْ فِي غَفْلَةٍ‏}‏ وَهَؤُلاَءِ فِي غَفْلَةٍ أَهْلُ الدُّنْيَا ‏{‏وَهُمْ لاَ يُؤْمِنُونَ‏}‏‏\"‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2849a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2849a","x":"Abu Sa'id reported Allah's Messenger (ﷺ) as saying:\n\nDeath would be brought on the Day of Resurrection. in the form of a white-coloured ram. Abu Kuraib made this addition: Then it would be made to stand between the Paradise and the Hell. So far as the rest of the hadith is concerned there is perfect agreement (between the two narrators) and it would be said to the inmates of Paradise: Do you recognise this? They would raise up their necks and look towards it and say: Yes, ' it is death. Then it would be said to the inmates of Hell-Fire.. Do you recognise this? And they would raise up their necks and look and say: Yes, it is death. Then command would be given for slaughtering that and then it would be said: 0 inmates of Paradise,, there is an everlasting life for you and no death. And then (addressing) to the inmates of the Hell-Fire, it would be said: 0 inmates of Hell-Fire, there is an everlasting living for you and no death. Allah's Messenger (may peace be u@on him) then recited this verse pointing with his hand to this (material) world:\" Warn them, this Day of dismay, and when their affairs would be decided and they would be un- mindful and they believe not\" (xix. 39).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَأَبُو كُرَيْبٍ - وَتَقَارَبَا فِي اللَّفْظِ - قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يُجَاءُ بِالْمَوْتِ يَوْمَ الْقِيَامَةِ كَأَنَّهُ كَبْشٌ أَمْلَحُ - زَادَ أَبُو كُرَيْبٍ - فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ - وَاتَّفَقَا فِي بَاقِي الْحَدِيثِ - فَيُقَالُ يَا أَهْلَ الْجَنَّةِ هَلْ تَعْرِفُونَ هَذَا فَيَشْرَئِبُّونَ وَيَنْظُرُونَ وَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ - قَالَ - وَيُقَالُ يَا أَهْلَ النَّارِ هَلْ تَعْرِفُونَ هَذَا قَالَ فَيَشْرَئِبُّونَ وَيَنْظُرُونَ وَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ - قَالَ - فَيُؤْمَرُ بِهِ فَيُذْبَحُ - قَالَ - ثُمَّ يُقَالُ يَا أَهْلَ الْجَنَّةِ خُلُودٌ فَلاَ مَوْتَ وَيَا أَهْلَ النَّارِ خُلُودٌ فَلاَ مَوْتَ ‏\"‏ ‏.‏ قَالَ ثُمَّ قَرَأَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏{‏ وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ إِذْ قُضِيَ الأَمْرُ وَهُمْ فِي غَفْلَةٍ وَهُمْ لاَ يُؤْمِنُونَ‏}‏ وَأَشَارَ بِيَدِهِ إِلَى الدُّنْيَا ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3156","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3156","x":"Narrated Abu Sa'eed Al-Khudri:\n\n\"The Messenger of Allah (ﷺ) recited: And warn them of a Day of griefs and regrets (19:39) and he said: 'Death will be brought as if it is a mixed black and white ram, until it is halted upon the barrier between Paradise and the Fire. It will be said: 'O people of Paradise! They will raise up their necks to look. It will be said: 'O people of the Fire! And they will raise up their necks to look. It will be said: 'Do you recognize this?' They will say: 'Yes. This is death.' Then it will be laid down and slaughtered. If it were not that Allah had decreed that the inhabitants of Paradise would remain, then they would die of joy, and if it were not that Allah had decreed that the inhabitants of the Fire would remain, then they would die of grief.'\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا النَّضْرُ بْنُ إِسْمَاعِيلَ أَبُو الْمُغِيرَةِ، عَنِ الأَعْمَشِ، عَنْ أَبِي صَالِحٍ، عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، رضى الله عنه قَالَ قَرَأَ رَسُولُ اللَّهِ صلى الله عليه وسلمَ ‏:‏ ‏(‏ وَأَنْذِرْهُمْ يَوْمَ الْحَسْرَةِ ‏)‏ قَالَ ‏\"‏ يُؤْتَى بِالْمَوْتِ كَأَنَّهُ كَبْشٌ أَمْلَحُ حَتَّى يُوقَفَ عَلَى السُّورِ بَيْنَ الْجَنَّةِ وَالنَّارِ فَيُقَالُ يَا أَهْلَ الْجَنَّةِ ‏.‏ فَيَشْرَئِبُّونَ ‏.‏ وَيُقَالُ يَا أَهْلَ النَّارِ ‏.‏ فَيَشْرَئِبُّونَ ‏.‏ فَيُقَالُ هَلْ تَعْرِفُونَ هَذَا فَيَقُولُونَ نَعَمْ هَذَا الْمَوْتُ ‏.‏ فَيُضْجَعُ فَيُذْبَحُ فَلَوْلاَ أَنَّ اللَّهَ قَضَى لأَهْلِ الْجَنَّةِ الْحَيَاةَ فِيهَا وَالْبَقَاءَ لَمَاتُوا فَرَحًا وَلَوْلاَ أَنَّ اللَّهَ قَضَى لأَهْلِ النَّارِ الْحَيَاةَ فِيهَا وَالْبَقَاءَ لَمَاتُوا تَرَحًا ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"57":[{"c":"Sahih Muslim","r":"Hadith 162a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-162a","x":"It is narrated on the authority of Anas b. Malik that the Messenger of Allah (ﷺ) said:\n\nI was brought al-Buraq Who is an animal white and long, larger than a donkey but smaller than a mule, who would place his hoof a distance equal to the range of version. I mounted it and came to the Temple (Bait Maqdis in Jerusalem), then tethered it to the ring used by the prophets. I entered the mosque and prayed two rak'ahs in it, and then came out and Gabriel brought me a vessel of wine and a vessel of milk. I chose the milk, and Gabriel said: You have chosen the natural thing. Then he took me to heaven. Gabriel then asked the (gate of heaven) to be opened and he was asked who he was. He replied: Gabriel. He was again asked: Who is with you? He (Gabriel) said: Muhammad. It was said: Has he been sent for? Gabriel replied: He has indeed been sent for. And (the door of the heaven) was opened for us and lo! we saw Adam. He welcomed me and prayed for my good. Then we ascended to the second heaven. Gabriel (peace be upon him) (asked the door of heaven to be opened), and he was asked who he was. He answered: Gabriel; and was again asked: Who is with you? He replied: Muhammad. It was said: Has he been sent for? He replied: He has indeed been sent for. The gate was opened. When I entered 'Isa b. Maryam and Yahya b. Zakariya (peace be upon both of them), cousins from the maternal side. welcomed me and prayed for my good Then I was taken to the third heaven and Gabriel asked for the opening (of the door). He was asked: Who are you? He replied: Gabriel. He was (again) asked: Who is with you? He replied Muhammad (ﷺ). It was said: Has he been sent for? He replied He has indeed been sent for. (The gate) was opened for us and I saw Yusuf (peace of Allah be upon him) who had been given half of (world) beauty. He welcomed me prayed for my well-being. Then he ascended with us to the fourth heaven. Gabriel (peace be upon him) asked for the (gate) to be opened, and it was said: Who is he? He replied: Gabriel. It was (again) said: Who is with you? He said: Muhammad. It was said: Has he been sent for? He replied: He has indeed been sent for. The (gate) was opened for us, and lo! Idris was there. He welcomed me and prayed for my well-being (About him) Allah, the Exalted and the Glorious, has said:\" We elevated him (Idris) to the exalted position\" (Qur'an xix. 57). Then he ascended with us to the fifth heaven and Gabriel asked for the (gate) to be opened. It was said: Who is he? He replied Gabriel. It was (again) said: Who is with thee? He replied: Muhammad. It was said Has he been sent for? He replied: He has indeed been sent for. (The gate) was opened for us and then I was with Harun (Aaron-peace of Allah be upon him). He welcomed me prayed for my well-being. Then I was taken to the sixth heaven. Gabriel (peace be upon him) asked for the door to be opened. It was said: Who is he? He replied: Gabriel. It was said: Who is with thee? He replied: Muhammad. It was said: Has he been sent for? He replied: He has indeed been sent for. (The gate) was opened for us and there I was with Musa (Moses peace be upon him) He welcomed me and prayed for my well-being. Then I was taken up to the seventh heaven. Gabriel asked the (gate) to be opened. It was said: Who is he? He said: Gabriel It was said. Who is with thee? He replied: Muhammad (may peace be upon him.) It was said: Has he been sent for? He replied: He has indeed been sent for. (The gate) was opened for us and there I found Ibrahim (Abraham peace be upon him) reclining against the Bait-ul-Ma'mur and there enter into it seventy thousand angels every day, never to visit (this place) again. Then I was taken to Sidrat-ul-Muntaha whose leaves were like elephant ears and its fruit like big earthenware vessels. And when it was covered by the Command of Allah, it underwent such a change that none amongst the creation has the power to praise its beauty. Then Allah revealed to me a revelation and He made obligatory for me fifty prayers every day and night. Then I went down to Moses (peace be upon him) and he said: What has your Lord enjoined upon your Ummah? I said: Fifty prayers. He said: Return to thy Lord and beg for reduction (in the number of prayers), for your community shallnot be able to bear this burden. as I have put to test the children of Isra'il and tried them (and found them too weak to bear such a heavy burden). He (the Holy Prophet) said: I went back to my Lord and said: My Lord, make things lighter for my Ummah. (The Lord) reduced five prayers for me. I went down to Moses and said. (The Lord) reduced five (prayers) for me, He said: Verily thy Ummah shall not be able to bear this burden; return to thy Lord and ask Him to make things lighter. I then kept going back and forth between my Lord Blessed and Exalted and Moses, till He said: There are five prayers every day and night. O Muhammad, each being credited as ten, so that makes fifty prayers. He who intends to do a good deed and does not do it will have a good deed recorded for him; and if he does it, it will be recorded for him as ten; whereas he who intends to do an evil deed and does not do, it will not be recorded for him; and if he does it, only one evil deed will be recorded. I then came down and when I came to Moses and informed him, he said: Go back to thy Lord and ask Him to make things lighter. Upon this the Messenger of Allah remarked: I returned to my Lord until I felt ashamed before Him.","ar":"حَدَّثَنَا شَيْبَانُ بْنُ فَرُّوخَ، حَدَّثَنَا حَمَّادُ بْنُ سَلَمَةَ، حَدَّثَنَا ثَابِتٌ الْبُنَانِيُّ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ أُتِيتُ بِالْبُرَاقِ - وَهُوَ دَابَّةٌ أَبْيَضُ طَوِيلٌ فَوْقَ الْحِمَارِ وَدُونَ الْبَغْلِ يَضَعُ حَافِرَهُ عِنْدَ مُنْتَهَى طَرْفِهِ - قَالَ فَرَكِبْتُهُ حَتَّى أَتَيْتُ بَيْتَ الْمَقْدِسِ - قَالَ - فَرَبَطْتُهُ بِالْحَلْقَةِ الَّتِي يَرْبِطُ بِهِ الأَنْبِيَاءُ - قَالَ - ثُمَّ دَخَلْتُ الْمَسْجِدَ فَصَلَّيْتُ فِيهِ رَكْعَتَيْنِ ثُمَّ خَرَجْتُ فَجَاءَنِي جِبْرِيلُ - عَلَيْهِ السَّلاَمُ - بِإِنَاءٍ مِنْ خَمْرٍ وَإِنَاءٍ مِنْ لَبَنٍ فَاخْتَرْتُ اللَّبَنَ فَقَالَ جِبْرِيلُ صلى الله عليه وسلم اخْتَرْتَ الْفِطْرَةَ ‏.‏ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ فَاسْتَفْتَحَ جِبْرِيلُ فَقِيلَ مَنْ أَنْتَ قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ ‏.‏ قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِآدَمَ فَرَحَّبَ بِي وَدَعَا لِي بِخَيْرٍ ‏.‏ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الثَّانِيَةِ فَاسْتَفْتَحَ جِبْرِيلُ عَلَيْهِ السَّلاَمُ ‏.‏ فَقِيلَ مَنْ أَنْتَ قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ ‏.‏ قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِابْنَىِ الْخَالَةِ عِيسَى ابْنِ مَرْيَمَ وَيَحْيَى بْنِ زَكَرِيَّاءَ صَلَوَاتُ اللَّهِ عَلَيْهِمَا فَرَحَّبَا وَدَعَوَا لِي بِخَيْرٍ ‏.‏ ثُمَّ عَرَجَ بِي إِلَى السَّمَاءِ الثَّالِثَةِ فَاسْتَفْتَحَ جِبْرِيلُ ‏.‏ فَقِيلَ مَنْ أَنْتَ قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ صلى الله عليه وسلم ‏.‏ قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِيُوسُفَ صلى الله عليه وسلم إِذَا هُوَ قَدْ أُعْطِيَ شَطْرَ الْحُسْنِ فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ ‏.‏ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الرَّابِعَةِ فَاسْتَفْتَحَ جِبْرِيلُ - عَلَيْهِ السَّلاَمُ - قِيلَ مَنْ هَذَا قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ ‏.‏ قَالَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِإِدْرِيسَ فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ وَرَفَعْنَاهُ مَكَانًا عَلِيًّا‏}‏ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الْخَامِسَةِ فَاسْتَفْتَحَ جِبْرِيلُ ‏.‏ قِيلَ مَنْ هَذَا قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ ‏.‏ قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِهَارُونَ صلى الله عليه وسلم فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ ‏.‏ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ السَّادِسَةِ فَاسْتَفْتَحَ جِبْرِيلُ عَلَيْهِ السَّلاَمُ ‏.‏ قِيلَ مَنْ هَذَا قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ ‏.‏ قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِمُوسَى صلى الله عليه وسلم فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ ‏.‏ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ السَّابِعَةِ فَاسْتَفْتَحَ جِبْرِيلُ فَقِيلَ مَنْ هَذَا قَالَ جِبْرِيلُ ‏.‏ قِيلَ وَمَنْ مَعَكَ قَالَ مُحَمَّدٌ صلى الله عليه وسلم ‏.‏ قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ ‏.‏ فَفُتِحَ لَنَا فَإِذَا أَنَا بِإِبْرَاهِيمَ صلى الله عليه وسلم مُسْنِدًا ظَهْرَهُ إِلَى الْبَيْتِ الْمَعْمُورِ وَإِذَا هُوَ يَدْخُلُهُ كُلَّ يَوْمٍ سَبْعُونَ أَلْفَ مَلَكٍ لاَ يَعُودُونَ إِلَيْهِ ثُمَّ ذَهَبَ بِي إِلَى السِّدْرَةِ الْمُنْتَهَى وَإِذَا وَرَقُهَا كَآذَانِ الْفِيَلَةِ وَإِذَا ثَمَرُهَا كَالْقِلاَلِ - قَالَ - فَلَمَّا غَشِيَهَا مِنْ أَمْرِ اللَّهِ مَا غَشِيَ تَغَيَّرَتْ فَمَا أَحَدٌ مِنْ خَلْقِ اللَّهِ يَسْتَطِيعُ أَنْ يَنْعَتَهَا مِنْ حُسْنِهَا ‏.‏ فَأَوْحَى اللَّهُ إِلَىَّ مَا أَوْحَى فَفَرَضَ عَلَىَّ خَمْسِينَ صَلاَةً فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَنَزَلْتُ إِلَى مُوسَى صلى الله عليه وسلم فَقَالَ مَا فَرَضَ رَبُّكَ عَلَى أُمَّتِكَ قُلْتُ خَمْسِينَ صَلاَةً ‏.‏ قَالَ ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ فَإِنَّ أُمَّتَكَ لاَ يُطِيقُونَ ذَلِكَ فَإِنِّي قَدْ بَلَوْتُ بَنِي إِسْرَائِيلَ وَخَبَرْتُهُمْ ‏.‏ قَالَ فَرَجَعْتُ إِلَى رَبِّي فَقُلْتُ يَا رَبِّ خَفِّفْ عَلَى أُمَّتِي ‏.‏ فَحَطَّ عَنِّي خَمْسًا فَرَجَعْتُ إِلَى مُوسَى فَقُلْتُ حَطَّ عَنِّي خَمْسًا ‏.‏ قَالَ إِنَّ أُمَّتَكَ لاَ يُطِيقُونَ ذَلِكَ فَارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ ‏.‏ - قَالَ - فَلَمْ أَزَلْ أَرْجِعُ بَيْنَ رَبِّي تَبَارَكَ وَتَعَالَى وَبَيْنَ مُوسَى - عَلَيْهِ السَّلاَمُ - حَتَّى قَالَ يَا مُحَمَّدُ إِنَّهُنَّ خَمْسُ صَلَوَاتٍ كُلَّ يَوْمٍ وَلَيْلَةٍ لِكُلِّ صَلاَةٍ عَشْرٌ فَذَلِكَ خَمْسُونَ صَلاَةً ‏.‏ وَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشْرًا وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ شَيْئًا فَإِنْ عَمِلَهَا كُتِبَتْ سَيِّئَةً وَاحِدَةً - قَالَ - فَنَزَلْتُ حَتَّى انْتَهَيْتُ إِلَى مُوسَى صلى الله عليه وسلم فَأَخْبَرْتُهُ فَقَالَ ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ ‏.‏ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقُلْتُ قَدْ رَجَعْتُ إِلَى رَبِّي حَتَّى اسْتَحْيَيْتُ مِنْهُ ‏\"‏ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3157","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3157","x":"Narrated Shaiban:\n\nfrom Qatadah, that regarding Allah's saying: And we raised him to a high station (19:57). He said: \"Anas bin Malik narrated that Allah's Prophet (ﷺ) said: \"When I was brought up, I saw Idris in the Fourth Heaven.\"","ar":"حَدَّثَنَا أَحْمَدُ بْنُ مَنِيعٍ، حَدَّثَنَا الْحُسَيْنُ بْنُ مُحَمَّدٍ، حَدَّثَنَا شَيْبَانُ، عَنْ قَتَادَةَ، فِي قَوْلِهِ ‏:‏ ‏(‏ورَفَعْنَاهُ مَكَانًا عَلِيًّا ‏)‏ قَالَ حَدَّثَنَا أَنَسُ بْنُ مَالِكٍ، أَنَّ نَبِيَّ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ لَمَّا عُرِجَ بِي رَأَيْتُ إِدْرِيسَ فِي السَّمَاءِ الرَّابِعَةِ ‏\"‏ ‏.‏ قَالَ وَفِي الْبَابِ عَنْ أَبِي سَعِيدٍ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ قَالَ وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ سَعِيدُ بْنُ أَبِي عَرُوبَةَ وَهَمَّامٌ وَغَيْرُ وَاحِدٍ عَنْ قَتَادَةَ عَنْ أَنَسٍ عَنْ مَالِكِ بْنِ صَعْصَعَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم حَدِيثَ الْمِعْرَاجِ بِطُولِهِ وَهَذَا عِنْدَنَا مُخْتَصَرٌ مِنْ ذَاكَ ‏.‏","v":[]}],"64":[{"c":"Sahih Bukhari","r":"Hadith 3218","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3218","x":"Narrated Ibn `Abbas:\n\nAllah's Messenger (ﷺ) asked Gabriel, \"Why don't you visit us more often than you do?\" Then the following Holy Verse was revealed (in this respect):-- \"And we (angels) descend not but by the order of your Lord. To Him belong what is before us and what is behind us, and what is between those two and your Lord was never forgetful.\" (19.64)","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا عُمَرُ بْنُ ذَرٍّ، ح قَالَ حَدَّثَنِي يَحْيَى بْنُ جَعْفَرٍ، حَدَّثَنَا وَكِيعٌ، عَنْ عُمَرَ بْنِ ذَرٍّ، عَنْ أَبِيهِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِجِبْرِيلَ ‏\"‏ أَلاَ تَزُورُنَا أَكْثَرَ مِمَّا تَزُورُنَا ‏\"‏ قَالَ فَنَزَلَتْ ‏{‏وَمَا نَتَنَزَّلُ إِلاَّ بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4731","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4731","x":"Narrated Ibn `Abbas:\n\nThe Prophet (ﷺ) said to Gabriel, \"What prevents you from visiting us more often than you visit us now?\" So there was revealed:-- 'And we (angels) descend not but by the command of your Lord. To Him belongs what is before us and what is behind us...'(19.64)","ar":"حَدَّثَنَا أَبُو نُعَيْمٍ، حَدَّثَنَا عُمَرُ بْنُ ذَرٍّ، قَالَ سَمِعْتُ أَبِي، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنه ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِجِبْرِيلَ ‏\"‏ مَا يَمْنَعُكَ أَنْ تَزُورَنَا أَكْثَرَ مِمَّا تَزُورُنَا فَنَزَلَتْ ‏{‏وَمَا نَتَنَزَّلُ إِلاَّ بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا‏}‏‏\"‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 7455","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-7455","x":"Narrated Ibn `Abbas:\n\nThe Prophet (ﷺ) said, \"O Gabriel, what prevents you. from visiting us more often than you do?\" Then this Verse was revealed:--'And we angels descend not but by Command of your Lord. To Him belongs what is before us and what is behind us..' (19.64) So this was the answer to Muhammad.","ar":"حَدَّثَنَا خَلاَّدُ بْنُ يَحْيَى، حَدَّثَنَا عُمَرُ بْنُ ذَرٍّ، سَمِعْتُ أَبِي يُحَدِّثُ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ ‏\"‏ يَا جِبْرِيلُ مَا يَمْنَعُكَ أَنْ تَزُورَنَا أَكْثَرَ مِمَّا تَزُورُنَا ‏\"‏‏.‏ فَنَزَلَتْ ‏{‏وَمَا نَتَنَزَّلُ إِلاَّ بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا‏}‏ إِلَى آخِرِ الآيَةِ‏.‏ قَالَ هَذَا كَانَ الْجَوَابَ لِمُحَمَّدٍ صلى الله عليه وسلم‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 365","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-365","x":"Ibn 'Abbas (May Allah be pleased with them) reported:\n\nThe Prophet (ﷺ) said to Jibril (Gabriel), \"What prevents you from visiting us more frequently?\" Thereupon was revealed the Ayah: \"(The angels say:) 'And we (angels) descend not except by the Command of your Rubb. To Him belongs what is before us and what is behind us, and what is between those two\". (19:64)[Al- Bukhari].","ar":"وعن ابن عباس رضي الله عنهما قال‏:‏ قال النبي صلى الله عليه وسلم لجبريل‏:‏ ما يمنعك أن تزورنا أكثر مما تزورنا‏؟‏‏\"‏ فنزلت ‏:‏‏{‏وما نتنزل إلا بأمر ربك له ما بين أيدينا وما خلفنا وما بين ذلك‏}‏ ‏(‏‏(‏رواه البخاري‏)‏‏)‏‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3158","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3158","x":"Narrated Sa'eed bin Jubair:\n\nfrom Ibn 'Abbas who said: \"The Messenger of Allah (ﷺ) said to Jibra'il: 'What prevents you from visiting us more than you visit us?'\" He said: \"So this Ayah was revealed: And we descend not except by the command of your Lord. To Him belongs what is before us and what is behind us.\" Up to the end of the Ayah (19:64).","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، حَدَّثَنَا يَعْلَى بْنُ عُبَيْدٍ، حَدَّثَنَا عُمَرُ بْنُ ذَرٍّ، عَنْ أَبِيهِ، عَنْ سَعِيدِ بْنِ جُبَيْرٍ، عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم لِجِبْرِيلَ ‏\"‏ مَا يَمْنَعُكَ أَنْ تَزُورَنَا أَكْثَرَ مِمَّا تَزُورُنَا ‏\"‏ ‏.‏ قَالَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏:‏ ‏(‏ومَا نَتَنَزَّلُ إِلاَّ بِأَمْرِ رَبِّكَ لَهُۥ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا ‏)‏ إِلَى آخِرِ الآيَةِ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ غَرِيبٌ ‏.‏ حَدَّثَنَا الْحُسَيْنُ بْنُ حُرَيْثٍ، حَدَّثَنَا وَكِيعٌ، عَنْ عُمَرَ بْنِ ذَرٍّ، نَحْوَهُ ‏.‏","v":[]}],"71":[{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4281","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4281","x":"It was narrated from Hafsah that the Prophet (ﷺ) said:\n\n\"I hope that no one of those who witnessed (the battle of) Badr and (Treaty) Hudaybiyah will enter Hell, if Allah wills.\" I said: \"O Messenger of Allah, doesn’t Allah say \"There is not one of you but will pass over it (Hell); this is with your Lord, a decree which must be accomplished?\" [19:71] He said: \"Have you not heard that He says: ‘Then We shall save those who use to fear Allah and were dutiful to Him. And We shall leave the wrongdoers therein (humbled) to their knees (in Hell)?’\" [19:72]","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، عَنْ أُمِّ مُبَشِّرٍ، عَنْ حَفْصَةَ، قَالَتْ قَالَ النَّبِيُّ ـ صلى الله عليه وسلم ـ ‏\"‏ إِنِّي لأَرْجُو أَلاَّ يَدْخُلَ النَّارَ أَحَدٌ إِنْ شَاءَ اللَّهُ تَعَالَى مِمَّنْ شَهِدَ بَدْرًا وَالْحُدَيْبِيَةَ ‏\"‏ ‏.‏ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَلَيْسَ قَدْ قَالَ اللَّهُ ‏{وَإِنْ مِنْكُمْ إِلاَّ وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا}‏ قَالَ ‏\"‏ أَلَمْ تَسْمَعِيهِ يَقُولُ ‏{ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا}‏ ‏.‏","v":[]},{"c":"Riyad as-Salihin","r":"Hadith 953","u":"https://quranx.com/Hadith/Saliheen/Reference/Hadith-953","x":"Abu Hurairah (May Allah be pleased with him) reported:\n\nThe Messenger of Allah (ﷺ) said, \"A Muslim whose three children die (in infancy) will not be touched by the Fire (of Hell) except for the fulfillment of Allah's Oath.\"[Al-Bukhari and Muslim].[Allah's Oath here refers to His Ayah: \"There is not one of you but will cross over it (Hell).\" (19:71) And the crossing will be across the 'Bridge' set over the Hell.]","ar":"وعن أبي هريرة رضي الله عنه قال‏:‏ قال رسول الله صلى الله عليه وسلم ‏:‏ \"لا يموت لأحد من المسلمين ثلاثة من الولد لا تمسه النار إلا تحلة القسم‏\"‏ ‏(‏‏(‏متفق عليه‏)‏‏)‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3159","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3159","x":"Narrated As-Suddi:\n\n\"I asked Murrah Al-Hamdani about the saying of Allah, Mighty and Sublime is He: There is not one of you but will pass over it (19:71). So he narrated to me that 'Abdullah bin Mas'ud narrated to him saying: 'The Messenger of Allah (ﷺ) said: \"The people will pass over the Fire, then they avert it based upon their deeds. The first of them (would pass over it) like a flash of lightening, then like the wind, then like a fleeing horse, then like a rider fleeing on a mount, then like a man fleeing, then like one walking.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عُبَيْدُ اللَّهِ بْنُ مُوسَى، عَنْ إِسْرَائِيلَ، عَنِ السُّدِّيِّ، قَالَ سَأَلْتُ مُرَّةَ الْهَمْدَانِيَّ عَنْ قَوْلِ اللَّهِ، عَزَّ وَجَلَّ ‏:‏ ‏(‏ وإِنْ مِنْكُمْ إِلاَّ وَارِدُهَا ‏)‏ فَحَدَّثَنِي أَنَّ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ حَدَّثَهُمْ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ يَرِدُ النَّاسُ النَّارَ ثُمَّ يَصْدُرُونَ مِنْهَا بِأَعْمَالِهِمْ فَأَوَّلُهُمْ كَلَمْحِ الْبَرْقِ ثُمَّ كَالرِّيحِ ثُمَّ كَحُضْرِ الْفَرَسِ ثُمَّ كَالرَّاكِبِ فِي رَحْلِهِ ثُمَّ كَشَدِّ الرَّجُلِ ثُمَّ كَمَشْيِهِ ‏\"‏ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ ‏.‏ وَرَوَاهُ شُعْبَةُ عَنِ السُّدِّيِّ فَلَمْ يَرْفَعْهُ ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3160","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3160","x":"Narrated Shu'bah:\n\nfrom As-Suffi from Murrah: \"'Abdullah said: 'There is not one of you but will pass over it (19:71) - They pass over it, then they avert it based upon their deeds.'\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا يَحْيَى بْنُ سَعِيدٍ، حَدَّثَنَا شُعْبَةُ، عَنِ السُّدِّيِّ، عَنْ مُرَّةَ، عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍِ ‏:‏ ‏(‏وإنْ مِنْكُمْ إِلاَّ وَارِدُهَا ‏)‏ قَالَ يَرِدُونَهَا ثُمَّ يَصْدُرُونَ بِأَعْمَالِهِمْ ‏.‏ حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ، عَنْ شُعْبَةَ، عَنِ السُّدِّيِّ، بِمِثْلِهِ ‏.‏ قَالَ عَبْدُ الرَّحْمَنِ قُلْتُ لِشُعْبَةَ إِنَّ إِسْرَائِيلَ حَدَّثَنِي عَنِ السُّدِّيِّ عَنْ مُرَّةَ عَنْ عَبْدِ اللَّهِ عَنِ النَّبِيِّ صلى الله عليه وسلم ‏.‏ قَالَ شُعْبَةُ وَقَدْ سَمِعْتُهُ مِنَ السُّدِّيِّ مَرْفُوعًا وَلَكِنِّي عَمْدًا أَدَعُهُ ‏.‏","v":[]}],"72":[{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4281","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4281","x":"It was narrated from Hafsah that the Prophet (ﷺ) said:\n\n\"I hope that no one of those who witnessed (the battle of) Badr and (Treaty) Hudaybiyah will enter Hell, if Allah wills.\" I said: \"O Messenger of Allah, doesn’t Allah say \"There is not one of you but will pass over it (Hell); this is with your Lord, a decree which must be accomplished?\" [19:71] He said: \"Have you not heard that He says: ‘Then We shall save those who use to fear Allah and were dutiful to Him. And We shall leave the wrongdoers therein (humbled) to their knees (in Hell)?’\" [19:72]","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ أَبِي سُفْيَانَ، عَنْ جَابِرٍ، عَنْ أُمِّ مُبَشِّرٍ، عَنْ حَفْصَةَ، قَالَتْ قَالَ النَّبِيُّ ـ صلى الله عليه وسلم ـ ‏\"‏ إِنِّي لأَرْجُو أَلاَّ يَدْخُلَ النَّارَ أَحَدٌ إِنْ شَاءَ اللَّهُ تَعَالَى مِمَّنْ شَهِدَ بَدْرًا وَالْحُدَيْبِيَةَ ‏\"‏ ‏.‏ قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ أَلَيْسَ قَدْ قَالَ اللَّهُ ‏{وَإِنْ مِنْكُمْ إِلاَّ وَارِدُهَا كَانَ عَلَى رَبِّكَ حَتْمًا مَقْضِيًّا}‏ قَالَ ‏\"‏ أَلَمْ تَسْمَعِيهِ يَقُولُ ‏{ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا}‏ ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2496","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2496","x":"Umm Mubashshir reported that she heard Allah's Apostle (ﷺ) as saying in presence of Hafsa:\n\nGod willing, the people of the Tree would never enter the fire of Hell one amongst those who owed allegiance under that. She said: Allah's Messenger, why not? He scolded her. Hafsa said: And there is none amongst you but shall have to pass over that (narrow Bridge). Thereupon Allah's Apostle (ﷺ) said: Allah, the Exalted and Glorious, has said: We would rescue those persons who are God-conscious and we would leave the tyrants to their fate there (xix. 72).","ar":"حَدَّثَنِي هَارُونُ بْنُ عَبْدِ اللَّهِ، حَدَّثَنَا حَجَّاجُ بْنُ مُحَمَّدٍ، قَالَ قَالَ ابْنُ جُرَيْجٍ أَخْبَرَنِي أَبُو الزُّبَيْرِ، أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ أَخْبَرَتْنِي أُمُّ مُبَشِّرٍ، أَنَّهَا سَمِعَتِ النَّبِيَّ صلى الله عليه وسلم يَقُولُ عِنْدَ حَفْصَةَ ‏\"‏ لاَ يَدْخُلُ النَّارَ إِنْ شَاءَ اللَّهُ مِنْ أَصْحَابِ الشَّجَرَةِ أَحَدٌ ‏.‏ الَّذِينَ بَايَعُوا تَحْتَهَا ‏\"‏ ‏.‏ قَالَتْ بَلَى يَا رَسُولَ اللَّهِ ‏.‏ فَانْتَهَرَهَا فَقَالَتْ حَفْصَةُ ‏{‏ وَإِنْ مِنْكُمْ إِلاَّ وَارِدُهَا‏}‏ فَقَالَ النَّبِيُّ صلى الله عليه وسلم ‏\"‏ قَدْ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ ثُمَّ نُنَجِّي الَّذِينَ اتَّقَوْا وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا‏}‏","v":[]}],"77":[{"c":"Sahih Bukhari","r":"Hadith 2091","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2091","x":"Narrated Khabbab:\n\nI was a blacksmith in the Pre-Islamic period, and 'Asi bin Wail owed me some money, so I went to him to demand it. He said (to me), \"I will not pay you unless you disbelieve Muhammad.\" I said, \"I will not disbelieve till Allah kills you and then you get resurrected.\" He said, \"Leave me till I die and get resurrected, then I will be given wealth and children and I will pay you your debt.\" On that occasion it was revealed to the Prophet: 'Have you seen him who disbelieved in Our signs and says: Surely I will be given wealth and children? Has he known the unseen, or has he taken a covenant from the Beneficent (Allah)? (19.77- 78)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ قَيْنًا فِي الْجَاهِلِيَّةِ، وَكَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَيْنٌ، فَأَتَيْتُهُ أَتَقَاضَاهُ قَالَ لاَ أُعْطِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ صلى الله عليه وسلم‏.‏ فَقُلْتُ لاَ أَكْفُرُ حَتَّى يُمِيتَكَ اللَّهُ، ثُمَّ تُبْعَثَ‏.‏ قَالَ دَعْنِي حَتَّى أَمُوتَ وَأُبْعَثَ، فَسَأُوتَى مَالاً وَوَلَدًا فَأَقْضِيَكَ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2275","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2275","x":"Narrated Khabbab:\n\nI was a blacksmith and did some work for Al-`As bin Wail. When he owed me some money for my work, I went to him to ask for that amount. He said, \"I will not pay you unless you disbelieve in Muhammad.\" I said, \"By Allah! I will never do that till you die and be resurrected.\" He said, \"Will I be dead and then resurrected after my death?\" I said, \"Yes.\" He said, \"There I will have property and offspring and then I will pay you your due.\" Then Allah revealed. 'Have you seen him who disbelieved in Our signs, and yet says: I will be given property and offspring?' (19.77)","ar":"حَدَّثَنَا عُمَرُ بْنُ حَفْصٍ، حَدَّثَنَا أَبِي، حَدَّثَنَا الأَعْمَشُ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، حَدَّثَنَا خَبَّابٌ، قَالَ كُنْتُ رَجُلاً قَيْنًا فَعَمِلْتُ لِلْعَاصِ بْنِ وَائِلٍ فَاجْتَمَعَ لِي عِنْدَهُ فَأَتَيْتُهُ أَتَقَاضَاهُ فَقَالَ لاَ وَاللَّهِ لاَ أَقْضِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ‏.‏ فَقُلْتُ أَمَا وَاللَّهِ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ فَلاَ‏.‏ قَالَ وَإِنِّي لَمَيِّتٌ ثُمَّ مَبْعُوثٌ قُلْتُ نَعَمْ‏.‏ قَالَ فَإِنَّهُ سَيَكُونُ لِي ثَمَّ مَالٌ وَوَلَدٌ فَأَقْضِيكَ‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 2425","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2425","x":"Narrated Khabbab:\n\nI was a blacksmith In the Pre-Islamic period of ignorance, and 'Asi bin Wail owed me some money. I went to him to demand it, but he said to me, \"I will not pay you unless you reject faith in Muhammad.\" I replied, \"By Allah, I will never disbelieve Muhammad till Allah let you die and then resurrect you.\" He said, \"Then wait till I die and come to life again, for then I will be given property and offspring and will pay your right.\" So, thus revelation came: \"Have you seen him who disbelieved in Our signs and yet says, 'I will be given property and offspring?' \" (19.77)","ar":"حَدَّثَنَا إِسْحَاقُ، حَدَّثَنَا وَهْبُ بْنُ جَرِيرِ بْنِ حَازِمٍ، أَخْبَرَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ قَيْنًا فِي الْجَاهِلِيَّةِ وَكَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَرَاهِمُ، فَأَتَيْتُهُ أَتَقَاضَاهُ فَقَالَ لاَ أَقْضِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ، فَقُلْتُ لاَ وَاللَّهِ لاَ أَكْفُرُ بِمُحَمَّدٍ صلى الله عليه وسلم حَتَّى يُمِيتَكَ اللَّهُ ثُمَّ يَبْعَثَكَ‏.‏ قَالَ فَدَعْنِي حَتَّى أَمُوتَ ثُمَّ أُبْعَثَ فَأُوتَى مَالاً وَوَلَدًا، ثُمَّ أَقْضِيَكَ‏.‏ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏ الآيَةَ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4732","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4732","x":"Narrated Khabbab:\n\nI came to Al-`Asi bin Wail As-Sahmi and demanded something which he owed me. He said, \"I will not give you (your money) till you disbelieve in Muhammad.\" I said, \"No, I shall not disbelieve in Muhammad till you die and then be resurrected.\" He said, \"Will I die and then be resurrected?\" I said, 'Yes'. He said', \"Then I will have wealth and children there, and I will pay you (there).\" So this Verse was revealed:-- 'Have you then seen him who disbelieved in Our Signs and (yet) says: I shall certainly be given wealth and children? (19.77)","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ سَمِعْتُ خَبَّابًا، قَالَ جِئْتُ الْعَاصِيَ بْنَ وَائِلٍ السَّهْمِيَّ أَتَقَاضَاهُ حَقًّا لِي عِنْدَهُ، فَقَالَ لاَ أُعْطِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ فَقُلْتُ لاَ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ‏.‏ قَالَ وَإِنِّي لَمَيِّتٌ ثُمَّ مَبْعُوثٌ قُلْتُ نَعَمْ‏.‏ قَالَ إِنَّ لِي هُنَاكَ مَالاً وَوَلَدًا فَأَقْضِيكَهُ، فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏ رَوَاهُ الثَّوْرِيُّ وَشُعْبَةُ وَحَفْصٌ وَأَبُو مُعَاوِيَةَ وَوَكِيعٌ عَنِ الأَعْمَشِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4734","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4734","x":"Narrated Masruq:\n\nKhabbab said, \"During the pre-lslamic period, I was a blacksmith and Al-Asi bin Wail owed me a debt.\" So Khabbab went to him to demand the debt. He said, \"I will not give you (your due) till you disbelieve in Muhammad.\" Khabbab said, \"By Allah, I shall not disbelieve in Muhammad till Allah makes you die and then resurrects you.\" Al-Asi said, \"So leave me till I die and then be resurrected, for I will be given wealth and children whereupon I will pay you your debt.\" So this Verse was revealed:-- 'Have you seen him who disbelieved in Our Signs and, (yet) says: I shall certainly be given wealth and children.' (19.77)","ar":"حَدَّثَنَا بِشْرُ بْنُ خَالِدٍ، حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، سَمِعْتُ أَبَا الضُّحَى، يُحَدِّثُ عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ قَيْنًا فِي الْجَاهِلِيَّةِ، وَكَانَ لِي دَيْنٌ عَلَى الْعَاصِي بْنِ وَائِلٍ قَالَ فَأَتَاهُ يَتَقَاضَاهُ، فَقَالَ لاَ أُعْطِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ فَقَالَ وَاللَّهِ لاَ أَكْفُرُ حَتَّى يُمِيتَكَ اللَّهُ ثُمَّ تُبْعَثَ‏.‏ قَالَ فَذَرْنِي حَتَّى أَمُوتَ ثُمَّ أُبْعَثَ، فَسَوْفَ أُوتَى مَالاً وَوَلَدًا، فَأَقْضِيكَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4735","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4735","x":"Narrated Khabbab:\n\nI was a blacksmith and Al-Asi Bin Wail owed me a debt, so I went to him to demand it. He said to me. \"I will not pay you your debt till you disbelieve in Muhammad.\" I said, \"I will not disbelieve in Muhammad till you die and then be resurrected.\" He said, \"Will I be resurrected after my death? If so, I shall pay you (there) if I should find wealth and children.\" So there was revealed:-- 'Have you seen him who disbelieved in Our Signs, and yet says: I shall certainly be given wealth and children? Has he, known to the unseen or has he taken a covenant from (Allah) the Beneficent? Nay ! We shall record what he says, and we shall add and add to his punishment. And We shall inherit from him all that he talks of, and he shall appear before Us alone.' (19.77-80)","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ رَجُلاً قَيْنًا، وَكَانَ لِي عَلَى الْعَاصِي بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ، فَقَالَ لِي لاَ أَقْضِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ‏.‏ قَالَ قُلْتُ لَنْ أَكْفُرَ بِهِ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ‏.‏ قَالَ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا * كَلاَّ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا * وَنَرِثُهُ مَا يَقُولُ وَيَأْتِينَا فَرْدًا‏}‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2795a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2795a","x":"Khabbab reported that Al-`As b. Wa'il owed debt to me. I came to him in order to demand that. He said:\n\nI will never repay you unless you belie Muhammad. I said: I would never belie Muhammad until you die and you are again raised up. He said: When I would be raised up after death, I would repay your debt when I would get my property and children back. Waki` said: This is how Al-A`mash has narrated and it was on this occasion that this verse was revealed: \"Hast thou seen him who disbelieves in Our message and says: I shall certainly be given wealth and children\" (xix, 77) up to \"he would come to Us alone\" (xix, 80).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَعَبْدُ اللَّهِ بْنُ سَعِيدٍ الأَشَجُّ، - وَاللَّفْظُ لِعَبْدِ اللَّهِ - قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ فَقَالَ لِي لَنْ أَقْضِيَكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ - قَالَ - فَقُلْتُ لَهُ إِنِّي لَنْ أَكْفُرَ بِمُحَمَّدٍ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ ‏.‏ قَالَ وَكِيعٌ كَذَا قَالَ الأَعْمَشُ قَالَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏ أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏ إِلَى قَوْلِهِ ‏{‏ وَيَأْتِينَا فَرْدًا‏}‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3162","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3162","x":"Narrated Masruq:\n\n\"I heard Khabbab bin Al-Aratt saying: 'I came to Al-'As bin Wa'il As-Sahmi to collect a debt he owed me. He said: 'You shall not be given anything until you deny Muhammad.' So I said: 'No, not until you are dead and resurrected.' He said: 'After I die and I am resurrected?' So I said: 'Yes.' So he said: 'I shall indeed have wealth and offspring to repay you with.' So (the following) Ayah was revealed: Have you seen him who disbelieved in Our Ayat and said: I shall certainly be given wealth and children (19:77).'\"","ar":"حَدَّثَنَا ابْنُ أَبِي عُمَرَ، حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ سَمِعْتُ خَبَّابَ بْنَ الأَرَتِّ، يَقُولُ جِئْتُ الْعَاصِيَ بْنَ وَائِلٍ السَّهْمِيَّ أَتَقَاضَاهُ حَقًّا لِي عِنْدَهُ فَقَالَ لاَ أُعْطِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ ‏.‏ فَقُلْتُ لاَ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ ‏.‏ قَالَ وَإِنِّي لَمَيِّتٌ ثُمَّ مَبْعُوثٌ فَقُلْتُ نَعَمْ ‏.‏ فَقَالَ إِنَّ لِي هُنَاكَ مَالاً وَوَلَدًا فَأَقْضِيكَ ‏.‏ فَنَزَلَتْ ‏:‏ ‏(‏ أَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا ‏)‏ الآيَةَ ‏.‏ حَدَّثَنَا هَنَّادٌ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، نَحْوَهُ ‏.‏ قَالَ هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"78":[{"c":"Sahih Bukhari","r":"Hadith 2091","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-2091","x":"Narrated Khabbab:\n\nI was a blacksmith in the Pre-Islamic period, and 'Asi bin Wail owed me some money, so I went to him to demand it. He said (to me), \"I will not pay you unless you disbelieve Muhammad.\" I said, \"I will not disbelieve till Allah kills you and then you get resurrected.\" He said, \"Leave me till I die and get resurrected, then I will be given wealth and children and I will pay you your debt.\" On that occasion it was revealed to the Prophet: 'Have you seen him who disbelieved in Our signs and says: Surely I will be given wealth and children? Has he known the unseen, or has he taken a covenant from the Beneficent (Allah)? (19.77- 78)","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ، حَدَّثَنَا ابْنُ أَبِي عَدِيٍّ، عَنْ شُعْبَةَ، عَنْ سُلَيْمَانَ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ قَيْنًا فِي الْجَاهِلِيَّةِ، وَكَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَيْنٌ، فَأَتَيْتُهُ أَتَقَاضَاهُ قَالَ لاَ أُعْطِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ صلى الله عليه وسلم‏.‏ فَقُلْتُ لاَ أَكْفُرُ حَتَّى يُمِيتَكَ اللَّهُ، ثُمَّ تُبْعَثَ‏.‏ قَالَ دَعْنِي حَتَّى أَمُوتَ وَأُبْعَثَ، فَسَأُوتَى مَالاً وَوَلَدًا فَأَقْضِيَكَ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا ‏}‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4735","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4735","x":"Narrated Khabbab:\n\nI was a blacksmith and Al-Asi Bin Wail owed me a debt, so I went to him to demand it. He said to me. \"I will not pay you your debt till you disbelieve in Muhammad.\" I said, \"I will not disbelieve in Muhammad till you die and then be resurrected.\" He said, \"Will I be resurrected after my death? If so, I shall pay you (there) if I should find wealth and children.\" So there was revealed:-- 'Have you seen him who disbelieved in Our Signs, and yet says: I shall certainly be given wealth and children? Has he, known to the unseen or has he taken a covenant from (Allah) the Beneficent? Nay ! We shall record what he says, and we shall add and add to his punishment. And We shall inherit from him all that he talks of, and he shall appear before Us alone.' (19.77-80)","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ رَجُلاً قَيْنًا، وَكَانَ لِي عَلَى الْعَاصِي بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ، فَقَالَ لِي لاَ أَقْضِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ‏.‏ قَالَ قُلْتُ لَنْ أَكْفُرَ بِهِ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ‏.‏ قَالَ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا * كَلاَّ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا * وَنَرِثُهُ مَا يَقُولُ وَيَأْتِينَا فَرْدًا‏}‏‏.‏","v":[]}],"79":[{"c":"Sahih Bukhari","r":"Hadith 4735","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4735","x":"Narrated Khabbab:\n\nI was a blacksmith and Al-Asi Bin Wail owed me a debt, so I went to him to demand it. He said to me. \"I will not pay you your debt till you disbelieve in Muhammad.\" I said, \"I will not disbelieve in Muhammad till you die and then be resurrected.\" He said, \"Will I be resurrected after my death? If so, I shall pay you (there) if I should find wealth and children.\" So there was revealed:-- 'Have you seen him who disbelieved in Our Signs, and yet says: I shall certainly be given wealth and children? Has he, known to the unseen or has he taken a covenant from (Allah) the Beneficent? Nay ! We shall record what he says, and we shall add and add to his punishment. And We shall inherit from him all that he talks of, and he shall appear before Us alone.' (19.77-80)","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ رَجُلاً قَيْنًا، وَكَانَ لِي عَلَى الْعَاصِي بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ، فَقَالَ لِي لاَ أَقْضِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ‏.‏ قَالَ قُلْتُ لَنْ أَكْفُرَ بِهِ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ‏.‏ قَالَ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا * كَلاَّ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا * وَنَرِثُهُ مَا يَقُولُ وَيَأْتِينَا فَرْدًا‏}‏‏.‏","v":[]}],"80":[{"c":"Sahih Bukhari","r":"Hadith 4735","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4735","x":"Narrated Khabbab:\n\nI was a blacksmith and Al-Asi Bin Wail owed me a debt, so I went to him to demand it. He said to me. \"I will not pay you your debt till you disbelieve in Muhammad.\" I said, \"I will not disbelieve in Muhammad till you die and then be resurrected.\" He said, \"Will I be resurrected after my death? If so, I shall pay you (there) if I should find wealth and children.\" So there was revealed:-- 'Have you seen him who disbelieved in Our Signs, and yet says: I shall certainly be given wealth and children? Has he, known to the unseen or has he taken a covenant from (Allah) the Beneficent? Nay ! We shall record what he says, and we shall add and add to his punishment. And We shall inherit from him all that he talks of, and he shall appear before Us alone.' (19.77-80)","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كُنْتُ رَجُلاً قَيْنًا، وَكَانَ لِي عَلَى الْعَاصِي بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ، فَقَالَ لِي لاَ أَقْضِيكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ‏.‏ قَالَ قُلْتُ لَنْ أَكْفُرَ بِهِ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ‏.‏ قَالَ فَنَزَلَتْ ‏{‏أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا * أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا * كَلاَّ سَنَكْتُبُ مَا يَقُولُ وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا * وَنَرِثُهُ مَا يَقُولُ وَيَأْتِينَا فَرْدًا‏}‏‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2795a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2795a","x":"Khabbab reported that Al-`As b. Wa'il owed debt to me. I came to him in order to demand that. He said:\n\nI will never repay you unless you belie Muhammad. I said: I would never belie Muhammad until you die and you are again raised up. He said: When I would be raised up after death, I would repay your debt when I would get my property and children back. Waki` said: This is how Al-A`mash has narrated and it was on this occasion that this verse was revealed: \"Hast thou seen him who disbelieves in Our message and says: I shall certainly be given wealth and children\" (xix, 77) up to \"he would come to Us alone\" (xix, 80).","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، وَعَبْدُ اللَّهِ بْنُ سَعِيدٍ الأَشَجُّ، - وَاللَّفْظُ لِعَبْدِ اللَّهِ - قَالاَ حَدَّثَنَا وَكِيعٌ، حَدَّثَنَا الأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، عَنْ خَبَّابٍ، قَالَ كَانَ لِي عَلَى الْعَاصِ بْنِ وَائِلٍ دَيْنٌ فَأَتَيْتُهُ أَتَقَاضَاهُ فَقَالَ لِي لَنْ أَقْضِيَكَ حَتَّى تَكْفُرَ بِمُحَمَّدٍ - قَالَ - فَقُلْتُ لَهُ إِنِّي لَنْ أَكْفُرَ بِمُحَمَّدٍ حَتَّى تَمُوتَ ثُمَّ تُبْعَثَ ‏.‏ قَالَ وَإِنِّي لَمَبْعُوثٌ مِنْ بَعْدِ الْمَوْتِ فَسَوْفَ أَقْضِيكَ إِذَا رَجَعْتُ إِلَى مَالٍ وَوَلَدٍ ‏.‏ قَالَ وَكِيعٌ كَذَا قَالَ الأَعْمَشُ قَالَ فَنَزَلَتْ هَذِهِ الآيَةُ ‏{‏ أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالاً وَوَلَدًا‏}‏ إِلَى قَوْلِهِ ‏{‏ وَيَأْتِينَا فَرْدًا‏}‏","v":[]}],"96":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3161","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3161","x":"Narrated Abu Hurairah:\n\nthat the Messenger of Allah (ﷺ) said: \"When Allah loves a slave He calls Jibra'il, (saying): 'Indeed I love so-and-so, so love him.'\" He said: \"So he calls out in the heavens. Then love for him descends among the people of the earth. That is as in the saying of Allah: Verily, those who believe and work deeds of righteousness, the Most Gracious will grant love for them (19:96). And when Allah hates a slave He calls out to Jibra'il, (saying): 'Indeed I hate so-and-so.' So he calls out in the heavens. Then hatred for him descends upon the earth.'\"","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ، عَنْ سُهَيْلِ بْنِ أَبِي صَالِحٍ، عَنْ أَبِيهِ، عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ إِذَا أَحَبَّ اللَّهُ عَبْدًا نَادَى جِبْرِيلَ إِنِّي قَدْ أَحْبَبْتُ فُلاَنًا فَأَحِبَّهُ قَالَ فَيُنَادِي فِي السَّمَاءِ ثُمَّ تَنْزِلُ لَهُ الْمَحَبَّةُ فِي أَهْلِ الأَرْضِ فَذَلِكَ قَوْلُ اللَّهِ ‏:‏ ‏(‏ إنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَيَجْعَلُ لَهُمُ الرَّحْمَنُ وُدًّا ‏)‏ وَإِذَا أَبْغَضَ اللَّهُ عَبْدًا نَادَى جِبْرِيلَ إِنِّي قَدْ أَبْغَضْتُ فُلاَنًا فَيُنَادِي فِي السَّمَاءِ ثُمَّ تَنْزِلُ لَهُ الْبَغْضَاءُ فِي الأَرْضِ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏ وَقَدْ رَوَى عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ دِينَارٍ عَنْ أَبِيهِ عَنْ أَبِي صَالِحٍ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صلى الله عليه وسلم نَحْوَ هَذَا ‏.‏","v":[]}]};